Function.prototype.myCall = function (thisArg, ...args) {
  if (typeof this !== 'function') throw new TypeError('myCall must be called on a function');
  const ctx = thisArg === null || thisArg === undefined ? globalThis : Object(thisArg);
  const key = Symbol('fn');
  Object.defineProperty(ctx, key, { value: this, configurable: true }); // not enumerable
  try {
    return ctx[key](...args);
  } finally {
    delete ctx[key];
  }
};

Function.prototype.myApply = function (thisArg, argsArray) {
  if (typeof this !== 'function') throw new TypeError('myApply must be called on a function');
  return this.myCall(thisArg, ...(argsArray ?? []));
};

const isSpace = (ch) => /\s/.test(ch);

String.prototype.myTrimStart = function () {
  const s = String(this);
  let i = 0;
  while (i < s.length && isSpace(s[i])) i++;
  return s.slice(i);
};

String.prototype.myTrimEnd = function () {
  const s = String(this);
  let j = s.length - 1;
  while (j >= 0 && isSpace(s[j])) j--;
  return s.slice(0, j + 1);
};

String.prototype.myTrim = function () {
  return this.myTrimStart().myTrimEnd();
};

Array.prototype.mySort = function (compareFn) {
  if (compareFn !== undefined && typeof compareFn !== 'function') throw new TypeError('compareFn must be a function');
  const cmp = compareFn || ((a, b) => {
    const x = String(a);
    const y = String(b);
    return x < y ? -1 : x > y ? 1 : 0;
  });

  const values = [];
  let undefs = 0;
  for (let i = 0; i < this.length; i++) {
    if (!(i in this)) continue;
    if (this[i] === undefined) undefs++;
    else values.push(this[i]);
  }

  const mergeSort = (list) => {
    if (list.length <= 1) return list;
    const mid = Math.floor(list.length / 2);
    const left = mergeSort(list.slice(0, mid));
    const right = mergeSort(list.slice(mid));
    const out = [];
    let i = 0;
    let j = 0;
    while (i < left.length && j < right.length) {
      if (cmp(left[i], right[j]) <= 0) out.push(left[i++]); // ties: left first = stable
      else out.push(right[j++]);
    }
    while (i < left.length) out.push(left[i++]);
    while (j < right.length) out.push(right[j++]);
    return out;
  };

  const sorted = mergeSort(values);
  let k = 0;
  for (const v of sorted) this[k++] = v;
  for (let u = 0; u < undefs; u++) this[k++] = undefined;
  for (; k < this.length; k++) delete this[k];
  return this;
};

problems.pseudo:
myResolve(value):
  if value is a real Promise -> return value
  return new Promise((res, rej) =>
    try:
      then = value is object/function ? value.then : undefined
      if then is a function -> call then with this = value, args (res, rej)
      else -> res(value)
    catch err -> rej(err)
  )

myReject(reason):
  return new Promise((_, rej) => rej(reason))   // no unwrapping

problems.solution:
Promise.myResolve = function (value) {
  if (value instanceof Promise) return value;
  return new Promise((resolve, reject) => {
    try {
      const then = value !== null && (typeof value === 'object' || typeof value === 'function') ? value.then : undefined;
      if (typeof then === 'function') then.call(value, resolve, reject);
      else resolve(value);
    } catch (err) {
      reject(err);
    }
  });
};

Promise.myReject = function (reason) {
  return new Promise((_, reject) => reject(reason));
};

