myReduceRight(cb, initialValue):
  if cb is not a function -> throw TypeError
  i = length - 1
  if arguments.length >= 2:
    acc = initialValue
  else:
    while i >= 0 and i is a hole: i--
    if i < 0 -> throw TypeError
    acc = this[i]; i--
  while i >= 0:
    if i is not a hole: acc = cb(acc, this[i], i, this)
    i--
  return acc

problems.solution:
Array.prototype.myReduceRight = function (cb, initialValue) {
  if (typeof cb !== 'function') throw new TypeError(cb + ' is not a function');
  let i = this.length - 1;
  let acc;
  if (arguments.length >= 2) {
    acc = initialValue;
  } else {
    while (i >= 0 && !(i in this)) i--;
    if (i < 0) throw new TypeError('Reduce of empty array with no initial value');
    acc = this[i--];
  }
  for (; i >= 0; i--) {
    if (i in this) acc = cb(acc, this[i], i, this);
  }
  return acc;
};
